"""Use the shared workbench surface for the exact authored operation states."""
import json,re,html

def build(R,D,source,header,toolbar,aux,css):
 guide=json.loads((D/'integrated/operation-guide.json').read_text())
 script=re.search(r'<script>([\s\S]*?)</script>',source).group(1)
 toolbar=toolbar.replace('id="view-reset"','id="operation-fit"')
 toolbar=re.sub(r'<button id="image-fit"[\s\S]*?<button id="model-retry"[^>]*>重试3D</button>','<button id="operation-retry" type="button" hidden>重试3D</button>',toolbar)
 hands='按压手只在外柄末端三孔上方；放取魔方的手和工具须完全离开四臂及托座运动区域。外柄手部隔离和控制联锁尚待实体验证，验证前不带电执行。'
 body=header+'''<section class="operation-heading" aria-label="当前位置"><h1>装卸动作演示</h1><p><a href="index.html">整机3D</a> / 放入、夹持交接、托座回落与取出 · 17阶段设计端姿</p></section><main class="workspace assembly operation"><section class="visual-column"><section class="viewport-shell" id="viewport-shell" aria-label="装卸动作查看区">'''+toolbar+'''<div class="reader-nav"><label class="sr-only" for="operation-select">选择动作阶段</label><select id="operation-select"></select><span id="operation-progress" class="reader-progress" aria-live="polite"></span></div><div class="viewer-stage" id="operation-v3d" tabindex="0" aria-label="整机阶段模型，可拖动旋转"><span id="operation-v3d-status" class="model-status" role="status">正在载入此阶段整机…</span><div id="operation-world-labels" aria-hidden="true"></div></div><div class="view-caption"><p id="operation-view-title"></p><p id="operation-result" role="status" aria-live="polite"></p><p>拖动旋转 · 滚轮 / 双指缩放 · R复位</p></div><div class="fullscreen-step-note" id="operation-fullscreen-note"><details><summary>本阶段说明与安全核对</summary><ol id="operation-expanded-instructions"></ol><ul id="operation-expanded-cautions"></ul></details><p>仅供设计审阅；未通过实体验收，不可照此操作实机。</p><p id="operation-expanded-hands" class="operation-hands-out" hidden>'''+hands+'''</p></div><div class="reader-bottom"><button id="operation-prev" type="button">上一阶段</button><span>设计端姿切换，不发送控制指令</span><button id="operation-next" type="button">下一阶段</button></div></section></section><aside id="operation-panel" class="instruction-panel" aria-labelledby="operation-title"><span id="operation-action-type" class="operation-action-type"></span><h2 id="operation-title"></h2><p class="scope-note">仅供设计审阅 · 不可照此操作实机</p><p id="operation-hands-out" class="operation-hands-out" hidden>'''+hands+'''</p><h3>此阶段的设计说明</h3><ol id="operation-instructions"></ol><section id="operation-cautions-box" class="check-box"><h3>停下核对</h3><ul id="operation-cautions"></ul></section><h3>当前支承与夹持</h3><dl class="operation-state"><dt>魔方支承</dt><dd id="operation-cube-support"></dd><dt>参考中心</dt><dd id="operation-cube-position"></dd><dt>四臂状态</dt><dd id="operation-arms"></dd><dt>托座</dt><dd id="operation-tray"></dd><dt>上位保持</dt><dd id="operation-keys"></dd></dl><figure id="operation-diagram" hidden><img id="operation-image" alt=""><figcaption id="operation-image-caption"></figcaption><a id="operation-image-open" target="_blank" rel="noopener">打开原图</a></figure><p id="operation-diagram-note"></p></aside></main>'''
 notes='<section class="aux"><details><summary>方向与魔方参考盒</summary><p>R=+X，L=−X，F=+Z，B=−Z，向上=−Y；画面左右随视角改变，臂名不变。</p><p>黄色透明盒是56毫米魔方位置参考，不计入882件LEGO；不代表实体零件或碰撞结论。A/D、W/S可旋转，+/-缩放，R复位。</p></details><details><summary>支承与四臂的关系</summary><ul>'+''.join('<li>'+html.escape(x)+'</li>'for x in guide['relationship_zh'])+'</ul></details></section>'
 # Downloads, final BOM and safety scope stay below the working surface, as on the overview.
 aux=re.sub(r'<details><summary>装卸动作演示</summary>[\s\S]*?</details>','',aux,count=1)
 body+=notes+aux+'<footer>最终结构 · 全机882件 / 底盘64 / 四臂668 / 支承150</footer>'
 result='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quadcuber · 装卸动作演示</title><style>'+css+'\n'+(R/'operation-workbench.css').read_text()+'</style></head><body data-mode="operation">'+body+'<script>'+script+'\n'+(R/'operation-workbench-ui.js').read_text()+'</script></body></html>'
 (D/'integrated-operation.html').write_text(result)
